// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // fuzzed params: depositor private key and deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep amount in a reasonable gas/chain range but allow zero too
        amount = bound(amount, 0, 1 ether);

        // derive depositor address from key so we can control its behavior (EOA)
        address depositor = vm.addr(uint256(depositorKey));

        // fund the depositor so it can deposit
        vm.deal(depositor, amount);

        // If amount==0 then withdrawAll is a no-op; the universal property still holds.
        // For amount>0 the reference contract should succeed when withdrawAll is called
        // because the external call to msg.sender (an EOA) will succeed. The mutant
        // inverts the require and will revert in that case.

        // make deposit from depositor
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now perform withdrawAll and observe whether it reverts. For the reference
        // implementation this should always succeed (ok==true). The mutant will
        // produce ok==false for some inputs (amount>0, recipient able to receive).
        bool ok;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: withdrawAll does not revert for any depositor/amount.
        // This holds on the reference contract for all fuzzed inputs; the mutant that
        // requires(!callResult) will break this for at least some inputs (positive amount).
        assertTrue(ok);
    }
}
